package com.axelsarassamit.ridedeck.dash;
import android.app.*;import android.os.*;import android.net.Uri;import android.content.*;import android.provider.MediaStore;import android.widget.*;import android.view.WindowManager;import java.io.*;import java.util.*;
import androidx.media3.common.*;import androidx.media3.transformer.*;import androidx.media3.effect.*;import androidx.media3.effect.Presentation;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class OverlayExportActivity extends Activity {
 Transformer transformer;File output;TextView progress;Button share;boolean completed,social;final Handler handler=new Handler(Looper.getMainLooper());
 public void onCreate(Bundle state){super.onCreate(state);social=getIntent().getBooleanExtra("social",false);LinearLayout page=DashUi.page(this);ScrollView scroll=new ScrollView(this);scroll.addView(page);setContentView(scroll);DashUi.text(this,page,social?"Create social video":"Export with overlays",28);progress=DashUi.text(this,page,"Preparing your video copy",18);DashUi.text(this,page,"Keep Dash open until export finishes. Your original recording is preserved. Rotating or leaving this screen cancels the export.",16);share=DashUi.button(this,page,"Share saved video",v->{});share.setVisibility(android.view.View.GONE);DashUi.button(this,page,"Close / cancel",v->finish());getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  if(state!=null){progress.setText("Export screen was recreated. Close and start a new export from your clip.");return;}
  try{if(RecordingService.running||RecordingService.finalizing)throw new IOException("Stop recording before exporting");if(!power())throw new IOException("Connect charger or charge to 50% before export");if(Build.VERSION.SDK_INT<29)throw new IOException("Gallery export requires Android 10 or newer");File clip=new File(getIntent().getStringExtra("clip"));if(!clip.getCanonicalPath().startsWith(new ClipStore(this).root().getCanonicalPath()+File.separator)||!ClipStore.finalized(clip))throw new IOException("Finalized clip unavailable");if(getCacheDir().getUsableSpace()<clip.length()*3+512L*1024*1024)throw new IOException("Not enough free space for an exported copy");
   output=new File(getCacheDir(),"export-"+System.currentTimeMillis()+".mp4");RideTelemetry telemetry=new RideTelemetry(clip);DashSettings settings=new DashSettings(this,true);List<Effect> effects=new ArrayList<>();MediaItem.Builder media=new MediaItem.Builder().setUri(Uri.fromFile(clip));long offsetUs=0;Transformer.Builder builder=new Transformer.Builder(this).setPortraitEncodingEnabled(social).setVideoMimeType(MimeTypes.VIDEO_H264).setAudioMimeType(MimeTypes.AUDIO_AAC);
   if(social){int[] size=SocialProfile.dimensions(settings.number("social_ratio",0),settings.number("social_quality",1080));android.media.MediaMetadataRetriever metadata=new android.media.MediaMetadataRetriever();long duration;try{metadata.setDataSource(clip.getPath());duration=Long.parseLong(metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION));}finally{metadata.release();}long[] range=SocialProfile.range(duration,settings.number("social_start",0),settings.number("social_length",15));offsetUs=range[0]*1000;media.setClippingConfiguration(new MediaItem.ClippingConfiguration.Builder().setStartPositionMs(range[0]).setEndPositionMs(range[1]).build());effects.add(Presentation.createForWidthAndHeight(size[0],size[1],settings.number("social_fit",0)==1?Presentation.LAYOUT_SCALE_TO_FIT_WITH_CROP:Presentation.LAYOUT_SCALE_TO_FIT));effects.add(FrameDropEffect.createDefaultFrameDropEffect(30));builder.setEncoderFactory(new DefaultEncoderFactory.Builder(this).setEnableFallback(false).setRequestedVideoEncoderSettings(new VideoEncoderSettings.Builder().setBitrate(settings.number("social_bitrate",8)*1000000).build()).build());Map<String,Object> values=new HashMap<>(settings.snapshot);int overlays=settings.number("social_overlay",0);if(overlays!=4)for(String key:SocialProfile.overlayKeys())values.put("overlay_"+key,SocialProfile.overlay(overlays,key)?1:0);settings=new DashSettings(this,values);DashUi.text(this,page,size[0]+" × "+size[1]+" · "+String.format(Locale.ROOT,"%.1f seconds",(range[1]-range[0])/1000.0)+" · "+(settings.number("social_fit",0)==1?"Center crop":"Whole picture"),16);}
   effects.add(new OverlayEffect(Collections.singletonList(new TelemetryOverlay(telemetry,settings,offsetUs,social))));
   transformer=builder.addListener(new Transformer.Listener(){
    @Override public void onCompleted(Composition composition,ExportResult result){completed=true;handler.removeCallbacks(tick);progress.setText("Saving to gallery");save(clip);}
    @Override public void onError(Composition composition,ExportResult result,ExportException error){handler.removeCallbacks(tick);progress.setText("Export failed: "+error.getMessage());if(output!=null)output.delete();}
   }).build();EditedMediaItem item=new EditedMediaItem.Builder(media.build()).setRemoveAudio(social&&settings.number("social_mute",0)==1).setEffects(new Effects(Collections.emptyList(),effects)).build();transformer.start(item,output.getPath());handler.post(tick);
  }catch(Exception e){progress.setText(e.getMessage());}
 }
 boolean power(){Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));return b!=null&&RecordingGate.evaluate(b.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)!=0,RecordingGate.batteryPercent(b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),b.getIntExtra(BatteryManager.EXTRA_SCALE,-1)),true,false)==RecordingGate.Result.ALLOWED;}
 final Runnable tick=new Runnable(){public void run(){if(transformer==null||completed||isDestroyed())return;if(!power()){transformer.cancel();if(output!=null)output.delete();progress.setText("Export stopped: connect charger or charge to 50%");return;}ProgressHolder holder=new ProgressHolder();if(transformer.getProgress(holder)==Transformer.PROGRESS_STATE_AVAILABLE)progress.setText("Creating video · "+holder.progress+"%");handler.postDelayed(this,500);}};
 void save(File clip){new Thread(()->{Uri uri=null;try{ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Dash-"+clip.getParentFile().getName()+"-"+clip.getName().replace(".mp4",social?"-social-"+System.currentTimeMillis()+".mp4":"-overlay-"+System.currentTimeMillis()+".mp4"));values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");values.put(MediaStore.Video.Media.RELATIVE_PATH,social?"Movies/RideDeckDash/Social":"Movies/RideDeckDash");values.put(MediaStore.Video.Media.IS_PENDING,1);uri=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Gallery unavailable");try(InputStream in=new FileInputStream(output);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Gallery unavailable");byte[] data=new byte[65536];int n;while((n=in.read(data))!=-1)out.write(data,0,n);}values.clear();values.put(MediaStore.Video.Media.IS_PENDING,0);getContentResolver().update(uri,values,null,null);final Uri saved=uri;runOnUiThread(()->{if(isDestroyed())return;progress.setText(social?"Saved in Movies / RideDeckDash / Social":"Saved in Movies / RideDeckDash");share.setVisibility(android.view.View.VISIBLE);share.setOnClickListener(v->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,saved).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share video")));});}catch(Exception error){if(uri!=null)getContentResolver().delete(uri,null,null);runOnUiThread(()->{if(!isDestroyed())progress.setText("Gallery export failed");});}finally{if(output!=null)output.delete();}},"DashExportGallery").start();}
 protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(transformer!=null&&!completed)transformer.cancel();if(output!=null&&!completed)output.delete();super.onDestroy();}
}
